  'onboarding.done': 'U kry!',
  'onboarding.learnedBasics': 'Shkëlqyer! Tani njeh zonat më të rëndësishme të HUI.',
  'onboarding.askAdvanced': 'Dëshiron të shohësh tutorialin e avancuar të HUI?',
  'onboarding.learnedAll': 'Tani njeh të gjitha zonat e HUI.',
  'tut.step1': 'Këtu i sheh të gjitha postimet kronologjikisht – feed-i yt personal.',
  'tut.step2': 'Këtu gjesh gjithçka rreth HUI: njerëz, vepra, përvoja dhe ide të reja.',
  'tut.step3': 'Këtu gjesh të gjitha projektet që mbështesim bashkërisht. Krijo një vetë!',
  'tut.step4': 'Këtu mund të dizajnosh dhe personalizosh profilin tënd.',
  'tut.step5': 'Këtu krijohen lidhjet. Shkruaj drejtpërdrejt njerëzve dhe mbaj kontakt.',
  'tut.step6': 'Këtu merr të gjitha lajmet e rëndësishme – komente, rezervime, blerje dhe më shumë.',
  'tut.step7': 'Këtu mbledh vepra që të prekin – hapësira jote personale për t\'i shikuar qetësisht dhe për t\'i blerë kur të jesh gati.',
  'tut.adv1': 'Këtu gjesh gjithçka ke krijuar. Veprat tregojnë aftësitë, kreativitetin dhe ndikimin tënd.',
  'tut.adv2': 'Këtu mund të ofrosh talentet e tua. Njerëzit mund të të rezervojnë, të mbështesin ose të bashkëpunojnë me ty.',
  'tut.adv3': 'Këtu lindin momente të veçanta dhe projekte të vërteta të zemrës. Mund të nisësh projektet e tua ose të marrësh pjesë në ato ekzistuese.',
  'tut.adv4': 'Momentet tregojnë çaste nga jeta jote e përditshme. Ata lidhin njerëzit dhe e bëjnë HUI të gjallë.',
  'tut.adv5': 'Këtu i sheh votat e tua të ndikimit dhe të gjitha projektet që mbështes. Çdo votë forcon pool-in e ndikimit.',
  'tut.adv6': 'Këtu gjesh blerjet dhe shitjet e tua. Gjithçka përpunohet me siguri nëpërmjet Stripe dhe dokumentohet në mënyrë transparente.',
  'tut.adv7': 'Këtu sheh se si reagojnë njerëzit ndaj teje – komente, frymëzime, ruajtje dhe më shumë. Rezonanca jote tregon se çfarë arrin tek të tjerët.',
  'tut.adv8': 'Këtu mblidhen rekomandimet nga njerëzit që kanë punuar me ty ose kanë bluar nga ti. Ato janë shenja më e sinqertë e cilësisë reale.',
